-- Snapshot of the production public schema (project hdjtgyvdlxwntfriqhff) taken
-- 2026-11-05 BEFORE the 20261105* migrations, generated from pg_catalog.
-- Structure only, no data. Used by prepare-db.sh so integration tests run
-- against the real production shape. pgvector is not available in CI, so
-- face_embeddings.embedding is real[] here (vector(512) in production).

CREATE TYPE public."tc_aiGenerationStatus" AS ENUM ('pending_review','partially_approved','approved','discarded');
CREATE TYPE public."tc_attemptStatus" AS ENUM ('calibrating','in_progress','submitted','reviewed','expired');
CREATE TYPE public."tc_eventType" AS ENUM ('face_missing','multiple_faces','tab_switch','fullscreen_exit','unknown_face','focus_change','head_away','gaze_deviation','camera_obstructed','behavior_anomaly','service_unavailable');
CREATE TYPE public."tc_membershipRole" AS ENUM ('teacher','student');
CREATE TYPE public."tc_questionType" AS ENUM ('mcq','multiple_select','true_false','fill_blank','short_answer','long_answer','numerical','coding');
CREATE TYPE public."tc_reviewStatus" AS ENUM ('pending','dismissed','concern');
CREATE TYPE public.tc_role AS ENUM ('user','admin','teacher','student');
CREATE TYPE public."tc_serviceStatus" AS ENUM ('ready','unavailable','fallback');
CREATE TYPE public.tc_severity AS ENUM ('low','medium','high');
CREATE TYPE public."tc_testDifficulty" AS ENUM ('easy','medium','hard');
CREATE TYPE public."tc_testStatus" AS ENUM ('draft','scheduled','live','completed','archived');

CREATE TABLE public.attempts (id uuid DEFAULT gen_random_uuid() NOT NULL, test_id uuid, student_id text NOT NULL, status text DEFAULT 'in_progress'::text NOT NULL, score numeric, answers jsonb DEFAULT '{}'::jsonb NOT NULL, violations jsonb DEFAULT '[]'::jsonb NOT NULL, started_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL, finished_at timestamp with time zone, submitted_at timestamp with time zone, created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL);
CREATE TABLE public.attendance (id uuid DEFAULT gen_random_uuid() NOT NULL, classroom_id uuid, student_id_legacy text NOT NULL, student_name text NOT NULL, status text DEFAULT 'Present'::text, verified_method text DEFAULT 'Face-ID Biometric'::text, verified_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL, session_id uuid, confidence numeric, verification_method text, student_id uuid NOT NULL, verification_attempt_id uuid, marked_by text, capture_metadata jsonb DEFAULT '{}'::jsonb NOT NULL, correction_version integer DEFAULT 0 NOT NULL, corrected_at timestamp with time zone, corrected_by text);
CREATE TABLE public.attendance_observations (id uuid DEFAULT gen_random_uuid() NOT NULL, session_id uuid NOT NULL, student_id uuid, track_id integer, status text NOT NULL, similarity numeric, confidence numeric, verification text, created_at timestamp with time zone DEFAULT now());
CREATE TABLE public.attendance_session_announcements (id uuid DEFAULT gen_random_uuid() NOT NULL, attendance_session_id uuid NOT NULL, classroom_id uuid NOT NULL, event_type text DEFAULT 'attendance_started'::text NOT NULL, session_code text, expires_at timestamp with time zone, created_at timestamp with time zone DEFAULT now(), radius_meters integer);
CREATE TABLE public.attendance_sessions (id uuid DEFAULT gen_random_uuid() NOT NULL, classroom_id uuid NOT NULL, teacher_id uuid, status text DEFAULT 'ACTIVE'::text NOT NULL, started_at timestamp with time zone DEFAULT now(), finished_at timestamp with time zone, title text DEFAULT 'Class attendance'::text NOT NULL, nonce text NOT NULL, starts_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL, ends_at timestamp with time zone, created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL, closed_at timestamp with time zone, challenge_token_hash text, pin_hash text, challenge_expires_at timestamp with time zone, challenge_rotated_at timestamp with time zone, verification_policy jsonb DEFAULT '{"pin": true, "liveness": false, "teacher_face": true}'::jsonb NOT NULL, network_session_id text, session_code text, teacher_latitude double precision, teacher_longitude double precision, teacher_location_accuracy double precision, radius_meters integer DEFAULT 100, expires_at timestamp with time zone, ended_at timestamp with time zone);
CREATE TABLE public.attendance_verification_attempts (id uuid DEFAULT gen_random_uuid() NOT NULL, session_id uuid NOT NULL, classroom_id uuid NOT NULL, student_user_id text NOT NULL, student_id text, idempotency_key text NOT NULL, challenge_digest text, status text NOT NULL, failure_reason text, device_fingerprint text, proximity_metadata jsonb DEFAULT '{}'::jsonb NOT NULL, liveness_metadata jsonb DEFAULT '{}'::jsonb NOT NULL, created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL);
CREATE TABLE public.attendance_verifications (id uuid DEFAULT gen_random_uuid() NOT NULL, attendance_session_id uuid NOT NULL, student_id uuid NOT NULL, student_user_id text NOT NULL, classroom_id uuid NOT NULL, network_connected boolean DEFAULT false, authentication_verified boolean DEFAULT false, classroom_verified boolean DEFAULT false, session_verified boolean DEFAULT false, face_detected boolean DEFAULT false, liveness_score numeric, face_match_score numeric, final_confidence numeric, verification_status text DEFAULT 'NOT_CONNECTED'::text, verified_at timestamp with time zone, attempt_count integer DEFAULT 0, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now(), location_status text DEFAULT 'LOCATION_UNAVAILABLE'::text, location_verified boolean DEFAULT false, student_latitude double precision, student_longitude double precision, location_accuracy double precision, distance_from_teacher double precision, overall_confidence numeric, manual_reviewed boolean DEFAULT false, manual_reviewed_by text, manual_review_reason text);
CREATE TABLE public.classroom_drive_folders (classroom_id uuid NOT NULL, connection_id uuid NOT NULL, drive_folder_id text NOT NULL, folder_name text NOT NULL, created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL, updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL);
CREATE TABLE public.classroom_material_chunks (id uuid DEFAULT gen_random_uuid() NOT NULL, material_id uuid NOT NULL, classroom_id uuid NOT NULL, chunk_index integer NOT NULL, content text NOT NULL, page_number integer, token_count integer, embedding jsonb, created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL);
CREATE TABLE public.classroom_materials (id uuid DEFAULT gen_random_uuid() NOT NULL, classroom_id uuid NOT NULL, uploader_id text NOT NULL, name text NOT NULL, storage_path text NOT NULL, mime_type text NOT NULL, extracted_text text, extraction_status text DEFAULT 'pending'::text NOT NULL, visibility text DEFAULT 'classroom'::text NOT NULL, size_bytes bigint DEFAULT 0 NOT NULL, checksum_sha256 text, page_count integer, chunk_count integer DEFAULT 0 NOT NULL, extraction_error text, retry_count integer DEFAULT 0 NOT NULL, metadata jsonb DEFAULT '{}'::jsonb NOT NULL, processed_at timestamp with time zone, created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL, source_type text DEFAULT 'local_upload'::text NOT NULL, drive_file_id text, drive_modified_at timestamp with time zone, drive_web_view_url text);
CREATE TABLE public.classrooms (id uuid DEFAULT gen_random_uuid() NOT NULL, name text NOT NULL, code text NOT NULL, subject text DEFAULT 'Computer Science'::text, user_id text NOT NULL, students integer DEFAULT 0, attendance text DEFAULT '0%'::text, status text DEFAULT 'Active'::text, created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL);
CREATE TABLE public.evaluations (id text NOT NULL, type text NOT NULL, studentname text NOT NULL, rollnumber text, subject text, assessmentname text, marksobtained numeric, totalmarks numeric, percentage numeric, grade text, feedback text, strengths jsonb, weaknesses jsonb, improvementsuggestions jsonb, date timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL);
CREATE TABLE public.face_embeddings (id uuid DEFAULT gen_random_uuid() NOT NULL, profile_id uuid NOT NULL, student_id uuid NOT NULL, classroom_id uuid NOT NULL, embedding real[] NOT NULL, source text NOT NULL, quality_score numeric, created_at timestamp with time zone DEFAULT now());
CREATE TABLE public.face_profile_versions (id uuid DEFAULT gen_random_uuid() NOT NULL, profile_id uuid NOT NULL, version integer NOT NULL, reason text NOT NULL, embedding_count integer NOT NULL, created_at timestamp with time zone DEFAULT now());
CREATE TABLE public.face_profiles (id uuid DEFAULT gen_random_uuid() NOT NULL, student_id uuid NOT NULL, classroom_id uuid NOT NULL, status text DEFAULT 'REGISTERED'::text NOT NULL, profile_version integer DEFAULT 1 NOT NULL, enrollment_count integer DEFAULT 0, verified_count integer DEFAULT 0, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now());
CREATE TABLE public.google_drive_connections (id uuid DEFAULT gen_random_uuid() NOT NULL, teacher_user_id text NOT NULL, google_email text, encrypted_refresh_token text NOT NULL, granted_scopes jsonb DEFAULT '[]'::jsonb NOT NULL, status text DEFAULT 'connected'::text NOT NULL, last_error text, created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL, updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL);
CREATE TABLE public.learning_feedback (id uuid DEFAULT gen_random_uuid() NOT NULL, thread_id uuid NOT NULL, message_id uuid NOT NULL, classroom_id uuid NOT NULL, student_user_id text NOT NULL, rating smallint NOT NULL, note text, created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL);
CREATE TABLE public.learning_messages (id uuid DEFAULT gen_random_uuid() NOT NULL, thread_id uuid NOT NULL, role text NOT NULL, content text NOT NULL, citations jsonb DEFAULT '[]'::jsonb NOT NULL, confidence text, answer_state text DEFAULT 'grounded'::text NOT NULL, follow_up text, created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL);
CREATE TABLE public.learning_observations (id uuid DEFAULT gen_random_uuid() NOT NULL, profile_id uuid NOT NULL, session_id uuid, similarity numeric, second_best_similarity numeric, margin numeric, quality_score numeric, status text NOT NULL, accepted_for_learning boolean DEFAULT false, rejection_reason text, created_at timestamp with time zone DEFAULT now());
CREATE TABLE public.learning_threads (id uuid DEFAULT gen_random_uuid() NOT NULL, classroom_id uuid NOT NULL, student_user_id text NOT NULL, title text DEFAULT 'Classroom learning thread'::text NOT NULL, learner_profile jsonb DEFAULT '{}'::jsonb NOT NULL, last_confidence text, last_source_count integer DEFAULT 0 NOT NULL, created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL);
CREATE TABLE public.students (id uuid DEFAULT gen_random_uuid() NOT NULL, classroom_id uuid, user_id text, name text NOT NULL, roll_number text, phone text, email text, face_samples jsonb DEFAULT '[]'::jsonb, joined_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL, face_descriptor jsonb, face_registration_status text DEFAULT 'NOT_REGISTERED'::text);
CREATE TABLE public.tc_ai_generation_logs (id character varying(64) NOT NULL, "teacherId" integer NOT NULL, "testId" character varying(64), provider character varying(100) NOT NULL, "requestPayload" text NOT NULL, "responsePayload" text NOT NULL, status "tc_aiGenerationStatus" DEFAULT 'pending_review'::"tc_aiGenerationStatus" NOT NULL, "createdAt" timestamp without time zone DEFAULT now() NOT NULL);
CREATE TABLE public.tc_attempt_answers (id integer NOT NULL, "attemptId" character varying(64) NOT NULL, "questionId" integer NOT NULL, answer text NOT NULL, "markedForReview" boolean DEFAULT false NOT NULL, "awardedMarks" double precision, "savedAt" timestamp without time zone DEFAULT now() NOT NULL);
CREATE TABLE public.tc_classroom_members ("classroomId" character varying(64) NOT NULL, "userId" integer NOT NULL, "membershipRole" "tc_membershipRole" NOT NULL, "joinedAt" timestamp without time zone DEFAULT now() NOT NULL);
CREATE TABLE public.tc_classrooms (id character varying(64) NOT NULL, "ownerId" integer NOT NULL, name character varying(200) NOT NULL, description text, "createdAt" timestamp without time zone DEFAULT now() NOT NULL, "updatedAt" timestamp without time zone DEFAULT now() NOT NULL);
CREATE TABLE public.tc_proctoring_attempt_states ("attemptId" character varying(64) NOT NULL, baseline text NOT NULL, "temporalState" text NOT NULL, "modelVersion" character varying(100), "lastRiskScore" double precision, "lastRiskLevel" tc_severity, "serviceStatus" "tc_serviceStatus" DEFAULT 'unavailable'::"tc_serviceStatus" NOT NULL, "updatedAt" timestamp without time zone DEFAULT now() NOT NULL);
CREATE TABLE public.tc_proctoring_events (id character varying(64) NOT NULL, "attemptId" character varying(64) NOT NULL, "testId" character varying(64) NOT NULL, "studentId" integer NOT NULL, "eventType" "tc_eventType" NOT NULL, severity tc_severity NOT NULL, confidence double precision, "anomalyScore" double precision, "riskScore" double precision, "durationSeconds" double precision, "evidenceKey" character varying(500), "modelVersion" character varying(100), "reviewStatus" "tc_reviewStatus" DEFAULT 'pending'::"tc_reviewStatus" NOT NULL, "reviewedBy" integer, "reviewedAt" timestamp without time zone, metadata text NOT NULL, "occurredAt" timestamp without time zone DEFAULT now() NOT NULL);
CREATE TABLE public.tc_question_options (id integer NOT NULL, "questionId" integer NOT NULL, "position" integer NOT NULL, text text NOT NULL, "isCorrect" boolean DEFAULT false NOT NULL);
CREATE TABLE public.tc_questions (id integer NOT NULL, "ownerId" integer NOT NULL, subject character varying(200) NOT NULL, type "tc_questionType" NOT NULL, "questionText" text NOT NULL, "imageKey" character varying(500), "codeSnippet" text, "correctAnswer" text NOT NULL, explanation text, marks double precision NOT NULL, "negativeMarks" double precision DEFAULT 0 NOT NULL, difficulty "tc_testDifficulty" NOT NULL, topic character varying(200) NOT NULL, "learningObjective" character varying(500), "createdAt" timestamp without time zone DEFAULT now() NOT NULL, "updatedAt" timestamp without time zone DEFAULT now() NOT NULL);
CREATE TABLE public.tc_test_assignments ("testId" character varying(64) NOT NULL, "studentId" integer NOT NULL, "accessPinHash" character varying(255), "approvedAt" timestamp without time zone, "createdAt" timestamp without time zone DEFAULT now() NOT NULL);
CREATE TABLE public.tc_test_attempts (id character varying(64) NOT NULL, "testId" character varying(64) NOT NULL, "studentId" integer NOT NULL, status "tc_attemptStatus" DEFAULT 'in_progress'::"tc_attemptStatus" NOT NULL, "startedAt" timestamp without time zone NOT NULL, "expiresAt" timestamp without time zone NOT NULL, "submittedAt" timestamp without time zone, score double precision, percentage double precision, "integrityScore" double precision, "reviewedAt" timestamp without time zone);
CREATE TABLE public.tc_test_questions ("testId" character varying(64) NOT NULL, "questionId" integer NOT NULL, "position" integer NOT NULL);
CREATE TABLE public.tc_test_settings ("testId" character varying(64) NOT NULL, config text NOT NULL, "updatedAt" timestamp without time zone DEFAULT now() NOT NULL);
CREATE TABLE public.tc_tests (id character varying(64) NOT NULL, "creatorId" integer NOT NULL, "classroomId" character varying(64), name character varying(250) NOT NULL, description text, subject character varying(200) NOT NULL, topic character varying(200), difficulty "tc_testDifficulty" DEFAULT 'medium'::"tc_testDifficulty" NOT NULL, instructions text, "totalMarks" double precision DEFAULT 0 NOT NULL, status "tc_testStatus" DEFAULT 'draft'::"tc_testStatus" NOT NULL, "bannerKey" character varying(500), "logoKey" character varying(500), "securityConfig" text NOT NULL, "scheduledStart" timestamp without time zone, "scheduledEnd" timestamp without time zone, "createdAt" timestamp without time zone DEFAULT now() NOT NULL, "updatedAt" timestamp without time zone DEFAULT now() NOT NULL);
CREATE TABLE public.tc_users (id integer NOT NULL, "openId" character varying(64) NOT NULL, name text, email character varying(320), "loginMethod" character varying(64), role tc_role DEFAULT 'user'::tc_role NOT NULL, "createdAt" timestamp without time zone DEFAULT now() NOT NULL, "updatedAt" timestamp without time zone DEFAULT now() NOT NULL, "lastSignedIn" timestamp without time zone DEFAULT now() NOT NULL);
CREATE TABLE public.test_results (id uuid DEFAULT gen_random_uuid() NOT NULL, test_id uuid, student_id uuid, score integer DEFAULT 0 NOT NULL, answers jsonb DEFAULT '{}'::jsonb NOT NULL, submitted_at timestamp with time zone DEFAULT now());
