CREATE TABLE public.users (id uuid DEFAULT gen_random_uuid() NOT NULL, uid text NOT NULL, email text NOT NULL, displayname text, photourl text, role text DEFAULT 'teacher'::text, createdat timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL, mobile_number text);
