CREATE TABLE public.x402_refund_cases (id uuid DEFAULT gen_random_uuid() NOT NULL, settlement_tx_id text NOT NULL, resource_id text NOT NULL, failure_code text NOT NULL, status text DEFAULT 'open'::text NOT NULL, operator_notes text, refund_tx_id text, created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL, updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL);

