-- Production policies as found (several are unsafe; fixed by 20261105000400)
CREATE POLICY "Allow anonymous select users" ON public.users FOR SELECT TO public USING (true);
CREATE POLICY "Allow anonymous insert users" ON public.users FOR INSERT TO public WITH CHECK (true);
CREATE POLICY "Allow anonymous select classrooms" ON public.classrooms FOR SELECT TO public USING (true);
CREATE POLICY "Allow anonymous insert classrooms" ON public.classrooms FOR INSERT TO public WITH CHECK (true);
CREATE POLICY "Allow anonymous select tests" ON public.tests FOR SELECT TO public USING (true);
CREATE POLICY "Allow anonymous insert tests" ON public.tests FOR INSERT TO public WITH CHECK (true);
CREATE POLICY "Allow anonymous select evaluations" ON public.evaluations FOR SELECT TO public USING (true);
CREATE POLICY "Allow anonymous insert evaluations" ON public.evaluations FOR INSERT TO public WITH CHECK (true);
CREATE POLICY "Allow anonymous select students" ON public.students FOR SELECT TO public USING (true);
CREATE POLICY "Allow anonymous insert students" ON public.students FOR INSERT TO public WITH CHECK (true);
CREATE POLICY "Allow anonymous update students" ON public.students FOR UPDATE TO public USING (true);
CREATE POLICY "Instructors manage tests for their classrooms" ON public.tests FOR ALL TO public USING ((EXISTS (SELECT 1 FROM classrooms c WHERE ((c.id = tests.classroom_id) AND (c.user_id = (auth.uid())::text)))));
CREATE POLICY "Students can view enrolled tests" ON public.tests FOR SELECT TO public USING ((EXISTS (SELECT 1 FROM students s WHERE ((s.classroom_id = tests.classroom_id) AND (s.user_id = (auth.uid())::text)))));
CREATE POLICY "Students manage own learning feedback" ON public.learning_feedback FOR ALL TO authenticated USING ((student_user_id = (auth.uid())::text)) WITH CHECK ((student_user_id = (auth.uid())::text));
CREATE POLICY "Students manage own results" ON public.test_results FOR ALL TO public USING ((EXISTS (SELECT 1 FROM students s WHERE ((s.id = test_results.student_id) AND (s.user_id = (auth.uid())::text)))));
CREATE POLICY "Instructors view test results" ON public.test_results FOR SELECT TO public USING ((EXISTS (SELECT 1 FROM (tests t JOIN classrooms c ON ((t.classroom_id = c.id))) WHERE ((t.id = test_results.test_id) AND (c.user_id = (auth.uid())::text)))));
CREATE POLICY "Authenticated users manage own or classroom attempts" ON public.attempts FOR ALL TO authenticated USING (((EXISTS (SELECT 1 FROM students s WHERE (((s.id)::text = attempts.student_id) AND (s.user_id = (auth.uid())::text)))) OR (EXISTS (SELECT 1 FROM (tests t JOIN classrooms c ON ((c.id = t.classroom_id))) WHERE ((t.id = attempts.test_id) AND (c.user_id = (auth.uid())::text)))))) WITH CHECK (((EXISTS (SELECT 1 FROM students s WHERE (((s.id)::text = attempts.student_id) AND (s.user_id = (auth.uid())::text)))) OR (EXISTS (SELECT 1 FROM (tests t JOIN classrooms c ON ((c.id = t.classroom_id))) WHERE ((t.id = attempts.test_id) AND (c.user_id = (auth.uid())::text))))));
CREATE POLICY "Authenticated users manage permitted submissions" ON public.test_submissions FOR ALL TO authenticated USING (((EXISTS (SELECT 1 FROM students s WHERE (((s.id)::text = test_submissions.student_id) AND (s.user_id = (auth.uid())::text)))) OR (EXISTS (SELECT 1 FROM (tests t JOIN classrooms c ON ((c.id = t.classroom_id))) WHERE ((t.id = test_submissions.test_id) AND (c.user_id = (auth.uid())::text)))))) WITH CHECK (((EXISTS (SELECT 1 FROM students s WHERE (((s.id)::text = test_submissions.student_id) AND (s.user_id = (auth.uid())::text)))) OR (EXISTS (SELECT 1 FROM (tests t JOIN classrooms c ON ((c.id = t.classroom_id))) WHERE ((t.id = test_submissions.test_id) AND (c.user_id = (auth.uid())::text))))));
CREATE POLICY "Allow attendance inserts for classroom owners and enrolled stud" ON public.attendance FOR ALL TO authenticated USING (((EXISTS (SELECT 1 FROM classrooms c WHERE ((c.id = attendance.classroom_id) AND (c.user_id = (auth.uid())::text)))) OR (EXISTS (SELECT 1 FROM students s WHERE (((s.id)::text = attendance.student_id_legacy) AND (s.user_id = (auth.uid())::text)))))) WITH CHECK (((EXISTS (SELECT 1 FROM classrooms c WHERE ((c.id = attendance.classroom_id) AND (c.user_id = (auth.uid())::text)))) OR (EXISTS (SELECT 1 FROM students s WHERE (((s.id)::text = attendance.student_id_legacy) AND (s.user_id = (auth.uid())::text))))));
CREATE POLICY face_profiles_student_read ON public.face_profiles FOR SELECT TO authenticated USING ((EXISTS (SELECT 1 FROM students s WHERE ((s.id = face_profiles.student_id) AND (s.user_id = (auth.uid())::text)))));
CREATE POLICY face_profiles_classroom_owner_read ON public.face_profiles FOR SELECT TO authenticated USING ((EXISTS (SELECT 1 FROM classrooms c WHERE ((c.id = face_profiles.classroom_id) AND (c.user_id = (auth.uid())::text)))));
CREATE POLICY attendance_sessions_classroom_owner_read ON public.attendance_sessions FOR SELECT TO authenticated USING ((EXISTS (SELECT 1 FROM classrooms c WHERE ((c.id = attendance_sessions.classroom_id) AND (c.user_id = (auth.uid())::text)))));
CREATE POLICY attendance_sessions_classroom_owner_update ON public.attendance_sessions FOR UPDATE TO authenticated USING ((EXISTS (SELECT 1 FROM classrooms c WHERE ((c.id = attendance_sessions.classroom_id) AND (c.user_id = (auth.uid())::text))))) WITH CHECK ((EXISTS (SELECT 1 FROM classrooms c WHERE ((c.id = attendance_sessions.classroom_id) AND (c.user_id = (auth.uid())::text)))));
CREATE POLICY attendance_observations_teacher_read ON public.attendance_observations FOR SELECT TO authenticated USING ((EXISTS (SELECT 1 FROM (attendance_sessions s JOIN classrooms c ON ((c.id = s.classroom_id))) WHERE ((s.id = attendance_observations.session_id) AND (c.user_id = (auth.uid())::text)))));
CREATE POLICY attendance_read_classroom_owner ON public.attendance FOR SELECT TO authenticated USING ((EXISTS (SELECT 1 FROM classrooms c WHERE ((c.id = attendance.classroom_id) AND (c.user_id = (auth.uid())::text)))));
CREATE POLICY "Teachers read classroom face profile versions" ON public.face_profile_versions FOR SELECT TO authenticated USING ((EXISTS (SELECT 1 FROM (face_profiles fp JOIN classrooms c ON ((c.id = fp.classroom_id))) WHERE ((fp.id = face_profile_versions.profile_id) AND (c.user_id = (auth.uid())::text)))));
CREATE POLICY "Teachers read classroom learning observations" ON public.learning_observations FOR SELECT TO authenticated USING ((EXISTS (SELECT 1 FROM (face_profiles fp JOIN classrooms c ON ((c.id = fp.classroom_id))) WHERE ((fp.id = learning_observations.profile_id) AND (c.user_id = (auth.uid())::text)))));
CREATE POLICY "Users can read face profiles in their classroom" ON public.face_profiles FOR SELECT TO authenticated USING (((EXISTS (SELECT 1 FROM classrooms c WHERE ((c.id = face_profiles.classroom_id) AND (c.user_id = (auth.uid())::text)))) OR (EXISTS (SELECT 1 FROM students s WHERE ((s.classroom_id = s.classroom_id) AND (s.user_id = (auth.uid())::text))))));
CREATE POLICY "Users can read face embeddings in their classroom" ON public.face_embeddings FOR SELECT TO authenticated USING (((EXISTS (SELECT 1 FROM classrooms c WHERE ((c.id = face_embeddings.classroom_id) AND (c.user_id = (auth.uid())::text)))) OR (EXISTS (SELECT 1 FROM students s WHERE ((s.classroom_id = s.classroom_id) AND (s.user_id = (auth.uid())::text))))));
CREATE POLICY "Students can view their own verifications" ON public.attendance_verifications FOR SELECT TO authenticated USING ((student_user_id = (auth.uid())::text));
CREATE POLICY "Teachers can view verifications for their classrooms" ON public.attendance_verifications FOR SELECT TO authenticated USING ((EXISTS (SELECT 1 FROM classrooms c WHERE ((c.id = attendance_verifications.classroom_id) AND (c.user_id = (auth.uid())::text)))));
CREATE POLICY "Students read announcements for enrolled classrooms" ON public.attendance_session_announcements FOR SELECT TO authenticated USING ((EXISTS (SELECT 1 FROM students s WHERE ((s.classroom_id = attendance_session_announcements.classroom_id) AND (s.user_id = (auth.uid())::text)))));
CREATE POLICY "Teachers manage announcements for owned classrooms" ON public.attendance_session_announcements FOR ALL TO authenticated USING ((EXISTS (SELECT 1 FROM classrooms c WHERE ((c.id = attendance_session_announcements.classroom_id) AND (c.user_id = (auth.uid())::text))))) WITH CHECK ((EXISTS (SELECT 1 FROM classrooms c WHERE ((c.id = attendance_session_announcements.classroom_id) AND (c.user_id = (auth.uid())::text)))));
CREATE POLICY "Classroom participants read materials" ON public.classroom_materials FOR SELECT TO authenticated USING (((uploader_id = (auth.uid())::text) OR (EXISTS (SELECT 1 FROM classrooms c WHERE ((c.id = classroom_materials.classroom_id) AND (c.user_id = (auth.uid())::text)))) OR (EXISTS (SELECT 1 FROM students s WHERE ((s.classroom_id = s.classroom_id) AND (s.user_id = (auth.uid())::text))))));
CREATE POLICY "Classroom participants read material chunks" ON public.classroom_material_chunks FOR SELECT TO authenticated USING (((EXISTS (SELECT 1 FROM classrooms c WHERE ((c.id = classroom_material_chunks.classroom_id) AND (c.user_id = (auth.uid())::text)))) OR (EXISTS (SELECT 1 FROM students s WHERE ((s.classroom_id = s.classroom_id) AND (s.user_id = (auth.uid())::text))))));
CREATE POLICY "Classroom owners read learning feedback" ON public.learning_feedback FOR SELECT TO authenticated USING ((EXISTS (SELECT 1 FROM classrooms c WHERE ((c.id = learning_feedback.classroom_id) AND (c.user_id = (auth.uid())::text)))));

